import { useCallback, useMemo, useState } from 'react';
import { Button, Calendar } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date;
  defaultValue?: Date;
  onChange?: (date: Date) => void;
};

type QuickOption = {
  key: string;
  label: string;
  resolve: () => Date;
};

const toStartOfDay = (date: Date): Date => {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
};

const addDays = (date: Date, days: number): Date => {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
};

const isSameDay = (a: Date, b: Date): boolean =>
  toStartOfDay(a).getTime() === toStartOfDay(b).getTime();

const buildQuickOptions = (): QuickOption[] => {
  const today = toStartOfDay(new Date());
  return [
    { key: 'today', label: 'Сегодня', resolve: () => today },
    { key: 'yesterday', label: 'Вчера', resolve: () => addDays(today, -1) },
    { key: 'week-ago', label: 'Неделя назад', resolve: () => addDays(today, -7) },
  ];
};

const ReportDatePicker = ({ value, defaultValue, onChange }: ReportDatePickerProps) => {
  const [internalDate, setInternalDate] = useState<Date>(() =>
    toStartOfDay(defaultValue ?? new Date())
  );

  const selectedDate = value ? toStartOfDay(value) : internalDate;
  const quickOptions = useMemo(buildQuickOptions, [selectedDate]);

  const selectDate = useCallback(
    (date: Date) => {
      const normalized = toStartOfDay(date);
      setInternalDate(normalized);
      onChange?.(normalized);
    },
    [onChange]
  );

  return (
    <div className="jx-stack jx-gap-md">
      <div className="jx-row jx-gap-sm" role="group" aria-label="Быстрый выбор даты">
        {quickOptions.map((option) => {
          const optionDate = option.resolve();
          const isActive = isSameDay(optionDate, selectedDate);
          return (
            <Button
              key={option.key}
              type="button"
              variant={isActive ? 'solid' : 'ghost'}
              size="sm"
              aria-pressed={isActive}
              onClick={() => selectDate(optionDate)}
            >
              {option.label}
            </Button>
          );
        })}
      </div>
      <Calendar
        value={selectedDate}
        onChange={selectDate}
        mode="single"
        aria-label="Дата отчёта"
      />
    </div>
  );
};

export default ReportDatePicker;

